//! The ore feature against vanilla's own output, block for block.
//!
//! Vectors: `golden/ore_vectors.json`, from `ci/ore-golden.sh`, which runs
//! `OreFeature.place` inside the jar over a 3x3 block of chunks generated by
//! the same pipeline the surface and carver gates measure.
//!
//! # What this gate asserts, in order of strength
//!
//! 1. **Every block changed, and no block not changed.** A vein is a set of
//!    positions and a set of states; both are compared.
//! 2. **The RNG's state afterwards.** Each case dumps `nextLong()` taken
//!    immediately after `place` returns. Two streams that agree on it agree
//!    on every draw that produced it, so this catches a draw-count error even
//!    in a case that placed nothing.
//! 3. **The draw count.** Not an independent check — it cannot fail while (2)
//!    passes — but it is the diagnostic: it says *how far* the streams parted
//!    rather than only that they did.
//! 4. **The parsed configs.** Both sides encode all thirty, and the port's
//!    parse of the datapack JSON must equal the jar's own codec output.
//!
//! # And the coverage it asserts alongside them
//!
//! A percentage says how often the port agreed on what it was asked, not how
//! much it was asked. So the gate also fails if the case set stops reaching
//! the branches it was built to reach: veins that place nothing, veins that
//! place something, the `discard_chance_on_air_exposure` draw, and a build
//! height check that comes back true.
//!
//! # What mutating the port found
//!
//! Three deliberate breakages, to establish that this gate can fail at all:
//!
//! | mutation | cases that failed |
//! |---|---|
//! | drop the swallowed-sphere deletion pass | 2 |
//! | drop the tested-bitset, so `canPlaceOre` runs twice per block | 20 |
//! | recompute `OCEAN_FLOOR_WG` from the final blocks | **0**, then 68 |
//!
//! The third one is why `SURFACE_OFFSETS` exists in the dumper. The probe in
//! `place` is a loose inequality against that heightmap, and every origin in
//! the original 1,440-case set sat either far below the terrain, where it
//! passes whatever the height is, or far above it, where it fails whatever
//! the height is. The heightmap could be wrong by 25 blocks — and recomputing
//! it *is* wrong, on 69% of the columns in these worlds — without moving a
//! single block.
//!
//! Origins at the terrain's own height plus a few blocks either way were
//! added until it failed. It now fails 68 of 1,980.

mod common;

use std::collections::BTreeMap;

use common::{data_path, expand_runs, have_extract, long, plain_name, read};
use rustmc_worldgen::feature::ore::{self, OreConfig, OreWorld};
use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
use rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource;
use rustmc_worldgen::rng::RandomSource;
use rustmc_worldgen::tags::BlockTags;
use serde_json::Value;

const GOLDEN: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/golden/ore_vectors.json");

/// Cases whose vein placed at least one block. Ratcheted: a case set that
/// stops placing ore would otherwise pass this gate perfectly.
const PLACING_FLOOR: usize = 800;
/// Cases that returned false — the early return, where three draws happen and
/// the feature never reaches `doPlace`.
const EMPTY_FLOOR: usize = 1170;
/// Cases in which `canPlaceOre` drew for the air-exposure discard. Detected by
/// the draw count exceeding what the vein's own draws account for.
///
/// Seven of the thirty configs carry a discard chance, but two of them carry
/// **1.0**, and `shouldSkipAirCheck` short-circuits at `>= 1` without
/// drawing. So only the five in between can reach the draw at all, and 161
/// cases find a block the rule test accepts and pay for it.
const AIR_CHECK_FLOOR: usize = 160;
/// Cases of the two `1.0` configs that reached `doPlace`. They are the proof
/// that the upper short-circuit is exercised rather than assumed: every one
/// of them must draw exactly the vein's own draws and no more.
const CERTAIN_DISCARD_FLOOR: usize = 80;

/// The 3x3 world a case runs in, decoded from the vectors.
///
/// It is loaded rather than regenerated. The terrain is already proved by
/// `golden_noise_chunk`, `golden_surface_chunk` and `golden_carver_chunk` at
/// 100.000000%, and regenerating it here would only add a way for this gate
/// to fail for a reason that is not about ore.
struct Region {
    center_x: i32,
    center_z: i32,
    min_y: i32,
    height: i32,
    /// Nine chunks, indexed `(dz + 1) * 3 + dx + 1`.
    blocks: Vec<Vec<String>>,
    /// `OCEAN_FLOOR_WG`, shipped rather than recomputed: it is a fossil of
    /// the terrain before the surface rules and the carvers touched it, and
    /// `ChunkStatusTasks.generateFeatures` primes every heightmap except this
    /// one before features run.
    ocean_floor: Vec<Vec<i32>>,
    write_radius: i32,
    /// Every write the running feature made, as `(x, y, z, was, now)`.
    ///
    /// A log rather than a before/after snapshot of the world, because a
    /// snapshot is 884,736 strings and there are 1,980 cases. It is also
    /// exact: the tested-bitset in `doPlace` means no position is written
    /// twice, so the log needs no deduplication.
    writes: Vec<(i32, i32, i32, String, String)>,
}

impl Region {
    fn parse(world: &Value, write_radius: i32) -> Self {
        let center_x = i32::try_from(world["centerX"].as_i64().expect("centerX")).expect("i32");
        let center_z = i32::try_from(world["centerZ"].as_i64().expect("centerZ")).expect("i32");
        let min_y = i32::try_from(world["minY"].as_i64().expect("minY")).expect("i32");
        let height = i32::try_from(world["height"].as_i64().expect("height")).expect("i32");

        let mut blocks = Vec::new();
        let mut ocean_floor = Vec::new();
        for (index, chunk) in world["chunks"]
            .as_array()
            .expect("chunks")
            .iter()
            .enumerate()
        {
            let dx = i32::try_from(index % 3).expect("i32") - 1;
            let dz = i32::try_from(index / 3).expect("i32") - 1;
            assert_eq!(
                chunk["chunkX"].as_i64().expect("chunkX"),
                i64::from(center_x + dx),
                "chunks are dumped x-inner, z-outer"
            );
            assert_eq!(
                chunk["chunkZ"].as_i64().expect("chunkZ"),
                i64::from(center_z + dz)
            );

            let palette: Vec<&str> = chunk["palette"]
                .as_array()
                .expect("palette")
                .iter()
                .map(|v| v.as_str().expect("block name"))
                .collect();
            let ids = expand_runs(palette.len(), &chunk["runs"]);
            assert_eq!(
                ids.len(),
                usize::try_from(height).expect("usize") * 256,
                "a chunk's runs must cover every block in it"
            );
            blocks.push(ids.into_iter().map(|i| palette[i].to_string()).collect());

            ocean_floor.push(
                chunk["oceanFloorWg"]
                    .as_array()
                    .expect("oceanFloorWg")
                    .iter()
                    .map(|v| i32::try_from(v.as_i64().expect("height")).expect("i32"))
                    .collect(),
            );
        }
        assert_eq!(blocks.len(), 9, "a world is a 3x3 block of chunks");

        Self {
            center_x,
            center_z,
            min_y,
            height,
            blocks,
            ocean_floor,
            write_radius,
            writes: Vec::new(),
        }
    }

    /// The writes of the case that just ran, in vanilla's dump order: y-major,
    /// then z, then x. Writes that changed nothing are dropped, because the
    /// oracle records a *difference* and cannot see them.
    fn changes(&self) -> Vec<(i32, i32, i32, String)> {
        let mut out: Vec<(i32, i32, i32, String)> = self
            .writes
            .iter()
            .filter(|(_, _, _, was, now)| was != now)
            .map(|(x, y, z, _, now)| (*x, *y, *z, now.clone()))
            .collect();
        out.sort_by_key(|(x, y, z, _)| (*y, *z, *x));
        out
    }

    /// Put the world back, so one divergence stays one failing case instead
    /// of poisoning every case after it.
    fn rewind(&mut self) {
        while let Some((x, y, z, was, _)) = self.writes.pop() {
            if let Some((c, i)) = self.locate(x, y, z) {
                self.blocks[c][i] = was;
            }
        }
    }

    /// `(chunk index, index within the chunk)`, or `None` outside the world.
    fn locate(&self, x: i32, y: i32, z: i32) -> Option<(usize, usize)> {
        if y < self.min_y || y >= self.min_y + self.height {
            return None;
        }
        let dx = (x >> 4) - self.center_x;
        let dz = (z >> 4) - self.center_z;
        assert!(
            (-1..=1).contains(&dx) && (-1..=1).contains(&dz),
            "the feature reached {x}, {z}, outside the 3x3 world around \
             {}, {} — the oracle would have thrown here",
            self.center_x,
            self.center_z
        );
        let chunk = usize::try_from((dz + 1) * 3 + dx + 1).expect("usize");
        let index =
            usize::try_from((y - self.min_y) * 256 + (z & 15) * 16 + (x & 15)).expect("usize");
        Some((chunk, index))
    }

    fn column(&self, x: i32, z: i32) -> (usize, usize) {
        let dx = (x >> 4) - self.center_x;
        let dz = (z >> 4) - self.center_z;
        assert!(
            (-1..=1).contains(&dx) && (-1..=1).contains(&dz),
            "column outside the world"
        );
        (
            usize::try_from((dz + 1) * 3 + dx + 1).expect("usize"),
            usize::try_from((z & 15) * 16 + (x & 15)).expect("usize"),
        )
    }
}

impl OreWorld for Region {
    fn ocean_floor(&mut self, x: i32, z: i32) -> i32 {
        let (chunk, index) = self.column(x, z);
        // `WorldGenRegion.getHeight` adds one to the chunk's own value.
        self.ocean_floor[chunk][index] + 1
    }

    fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
        self.locate(x, y, z).map_or_else(
            || "minecraft:air".to_string(),
            |(c, i)| self.blocks[c][i].clone(),
        )
    }

    fn set_block(&mut self, x: i32, y: i32, z: i32, name: &str) {
        if let Some((c, i)) = self.locate(x, y, z) {
            let was = std::mem::replace(&mut self.blocks[c][i], name.to_string());
            self.writes.push((x, y, z, was, name.to_string()));
        }
    }

    fn outside_build_height(&self, y: i32) -> bool {
        y < self.min_y || y >= self.min_y + self.height
    }

    fn can_write(&self, x: i32, _y: i32, z: i32) -> bool {
        ((x >> 4) - self.center_x).abs() <= self.write_radius
            && ((z >> 4) - self.center_z).abs() <= self.write_radius
    }
}

/// A source that counts its draws, so the gate can report *how far* two
/// streams parted rather than only that they did.
struct Counting<R: RandomSource> {
    inner: R,
    draws: usize,
}

impl<R: RandomSource> RandomSource for Counting<R> {
    fn set_seed(&mut self, seed: i64) {
        self.inner.set_seed(seed);
    }
    fn next_i32(&mut self) -> i32 {
        self.draws += 1;
        self.inner.next_i32()
    }
    fn next_i32_bound(&mut self, bound: i32) -> i32 {
        self.draws += 1;
        self.inner.next_i32_bound(bound)
    }
    fn next_i64(&mut self) -> i64 {
        self.draws += 1;
        self.inner.next_i64()
    }
    fn next_bool(&mut self) -> bool {
        self.draws += 1;
        self.inner.next_bool()
    }
    fn next_f32(&mut self) -> f32 {
        self.draws += 1;
        self.inner.next_f32()
    }
    fn next_f64(&mut self) -> f64 {
        self.draws += 1;
        self.inner.next_f64()
    }
    fn next_gaussian(&mut self) -> f64 {
        self.draws += 1;
        self.inner.next_gaussian()
    }
}

#[test]
fn ore_features_match_vanilla_block_for_block() {
    if !have_extract() {
        return;
    }
    let doc = read(GOLDEN);
    let seed = long(&doc["seed"]);
    let step = i32::try_from(doc["step"].as_i64().expect("step")).expect("i32");
    let write_radius =
        i32::try_from(doc["writeRadius"].as_i64().expect("writeRadius")).expect("i32");

    let tags = BlockTags::load(&data_path("tags/block")).expect("block tags");
    let configs = parsed_configs(&doc, &tags);

    let mut regions: Vec<Region> = doc["worlds"]
        .as_array()
        .expect("worlds")
        .iter()
        .map(|w| Region::parse(w, write_radius))
        .collect();

    let vectors = doc["vectors"].as_array().expect("vectors");
    let per_region = vectors.len() / regions.len();
    assert_eq!(
        per_region * regions.len(),
        vectors.len(),
        "cases must divide evenly across worlds"
    );

    let mut checked = 0usize;
    let mut blocks_placed = 0usize;
    let mut placing = 0usize;
    let mut empty = 0usize;
    let mut air_checks = 0usize;
    let mut certain_discards = 0usize;
    let mut mismatches: Vec<String> = Vec::new();

    for (region_index, region) in regions.iter_mut().enumerate() {
        for vector in &vectors[region_index * per_region..(region_index + 1) * per_region] {
            let name = vector["feature"].as_str().expect("feature");
            let config = configs
                .get(name)
                .unwrap_or_else(|| panic!("{name} not parsed"));
            let origin = vector["origin"].as_array().expect("origin");
            let ox = i32::try_from(origin[0].as_i64().expect("x")).expect("i32");
            let oy = i32::try_from(origin[1].as_i64().expect("y")).expect("i32");
            let oz = i32::try_from(origin[2].as_i64().expect("z")).expect("i32");
            let index = i32::try_from(vector["index"].as_i64().expect("index")).expect("i32");

            // Vanilla's own seeding, in vanilla's own order.
            let mut random = WorldgenRandom::new(XoroshiroRandomSource::from_seed(0));
            let population =
                random.set_decoration_seed(seed, region.center_x * 16, region.center_z * 16);
            random.set_feature_seed(population, index, step);
            let mut counting = Counting {
                inner: random,
                draws: 0,
            };

            let placed = ore::place(region, &tags, config, &mut counting, (ox, oy, oz));
            let after = counting.inner.next_i64();

            let expected_placed = vector["placed"].as_bool().expect("placed");
            let expected_after = long(&vector["after"]);
            let expected_draws =
                usize::try_from(vector["draws"].as_u64().expect("draws")).expect("usize");

            if placed != expected_placed
                || after != expected_after
                || counting.draws != expected_draws
            {
                mismatches.push(format!(
                    "{name} at {ox},{oy},{oz}: placed {placed} (want {expected_placed}), \
                     draws {} (want {expected_draws}), next {after} (want {expected_after})",
                    counting.draws
                ));
            }

            let changes = region.changes();
            let expected: Vec<(i32, i32, i32, String)> = vector["changes"]
                .as_array()
                .expect("changes")
                .iter()
                .map(|c| {
                    let c = c.as_array().expect("[x, y, z, name]");
                    (
                        i32::try_from(c[0].as_i64().expect("x")).expect("i32"),
                        i32::try_from(c[1].as_i64().expect("y")).expect("i32"),
                        i32::try_from(c[2].as_i64().expect("z")).expect("i32"),
                        c[3].as_str().expect("name").to_string(),
                    )
                })
                .collect();
            if changes != expected {
                mismatches.push(format!(
                    "{name} at {ox},{oy},{oz}: {} blocks changed, vanilla changed {}; \
                     first difference {:?} vs {:?}",
                    changes.len(),
                    expected.len(),
                    changes
                        .iter()
                        .zip(&expected)
                        .find(|(a, b)| a != b)
                        .map(|(a, _)| a),
                    changes
                        .iter()
                        .zip(&expected)
                        .find(|(a, b)| a != b)
                        .map(|(_, b)| b),
                ));
            }

            region.rewind();

            blocks_placed += expected.len();
            checked += 1;
            if expected_placed {
                placing += 1;
            } else {
                empty += 1;
            }
            // Draws beyond the vein's own account for the air-exposure
            // discard: one `nextFloat` for the direction, two `nextInt` for
            // the y offsets, and one `nextDouble` per sample point.
            let own = if expected_placed || expected_draws > 3 {
                3 + usize::try_from(config.size.max(0)).expect("usize")
            } else {
                3
            };
            if expected_draws > own {
                air_checks += 1;
            }
            // `shouldSkipAirCheck` returns true without drawing when the
            // chance is >= 1. If that short-circuit were missing, these
            // configs would draw once per candidate block like the others.
            if config.discard_chance_on_air_exposure >= 1.0 && expected_draws > 3 {
                certain_discards += 1;
                assert_eq!(
                    expected_draws, own,
                    "{name} discards on air with certainty, so it must never draw for the \
                     check — vanilla drew {expected_draws}, the vein alone accounts for {own}"
                );
            }
        }
    }

    assert!(
        mismatches.is_empty(),
        "{} of {checked} ore cases disagree with vanilla:\n{}",
        mismatches.len(),
        mismatches
            .iter()
            .take(12)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );

    assert!(
        placing >= PLACING_FLOOR,
        "only {placing} cases placed a block, floor is {PLACING_FLOOR} — the case set has \
         stopped exercising the vein"
    );
    assert!(
        empty >= EMPTY_FLOOR,
        "only {empty} cases returned false, floor is {EMPTY_FLOOR} — the early return is \
         no longer covered"
    );
    assert!(
        air_checks >= AIR_CHECK_FLOOR,
        "only {air_checks} cases drew for the air-exposure discard, floor is \
         {AIR_CHECK_FLOOR}"
    );
    assert!(
        certain_discards >= CERTAIN_DISCARD_FLOOR,
        "only {certain_discards} cases reached a config that discards with certainty, \
         floor is {CERTAIN_DISCARD_FLOOR} — the upper short-circuit is unproven"
    );
    // The header counters are the oracle's own tally. Comparing them against
    // the ones counted here catches a truncated or half-written vector file,
    // which would otherwise read as a smaller gate that passes.
    assert_eq!(
        doc["cases"].as_u64().expect("cases"),
        checked as u64,
        "the vector file says how many cases it holds, and it does not hold that many"
    );
    assert_eq!(doc["placed"].as_u64().expect("placed"), placing as u64);
    assert_eq!(doc["empty"].as_u64().expect("empty"), empty as u64);
    assert_eq!(
        doc["writeDenied"].as_u64().expect("writeDenied"),
        0,
        "vanilla denied a write, so `ensureCanWrite` is behaviour here and the port's \
         `can_write` needs its own case"
    );
    assert!(
        doc["outsideBuildHeight"]
            .as_u64()
            .expect("outsideBuildHeight")
            > 0,
        "no case reached the build-height check"
    );

    println!(
        "ORE PARITY: {checked} cases, {blocks_placed} blocks placed, 100.000000%\n\
         COVERAGE: {placing} veins ran, {empty} returned early, {air_checks} drew for \
         air exposure, {certain_discards} short-circuited it"
    );
}

/// The port's parse of the datapack must equal the jar's own codec output.
///
/// The jar ships each config encoded through `OreConfiguration.CODEC`, and
/// the port reads the datapack file of the same name. Parsing both and
/// comparing proves the extract matches the registry — a divergence there
/// would otherwise show up as a parity failure whose cause is nowhere near
/// the ore code.
fn parsed_configs(doc: &Value, tags: &BlockTags) -> BTreeMap<String, OreConfig> {
    let states = rustmc_worldgen::feature::state_spec::extract_or_skip()
        .expect("the ore gate needs the block-props extract for default states");
    let mut out = BTreeMap::new();
    for entry in doc["configs"].as_array().expect("configs") {
        let name = entry["name"].as_str().expect("name");
        let from_jar = OreConfig::parse(&entry["config"], &states)
            .unwrap_or_else(|e| panic!("{name} from the jar: {e}"));

        let file = data_path(&format!(
            "worldgen/configured_feature/{}.json",
            name.strip_prefix("minecraft:")
                .expect("minecraft namespace")
        ));
        let json: Value = serde_json::from_str(
            &std::fs::read_to_string(&file).unwrap_or_else(|e| panic!("{}: {e}", file.display())),
        )
        .expect("json");
        let from_data = OreConfig::parse(&json["config"], &states)
            .unwrap_or_else(|e| panic!("{name} from data: {e}"));

        assert_eq!(
            from_jar, from_data,
            "{name} differs between the jar's registry and the datagen extract"
        );
        // Every target's rule has to resolve against a real tag, or the
        // feature silently replaces nothing — the same shape of fault that
        // made 567 carvers touch zero blocks.
        for (rule, _) in &from_jar.targets {
            assert!(
                rule.test(tags, "minecraft:stone")
                    || rule.test(tags, "minecraft:deepslate")
                    || rule.test(tags, "minecraft:netherrack")
                    || rule.test(tags, "minecraft:end_stone")
                    || rule.test(tags, "minecraft:tuff"),
                "{name}: rule {rule:?} matches none of the common host blocks, which \
                 usually means its tag resolved empty"
            );
        }
        out.insert(name.to_string(), from_jar);
    }
    assert_eq!(out.len(), 30, "the registry holds thirty ore configs");
    out
}

/// The palette names in the vectors carry no state suffix, and the port's
/// target states do. They have to agree, or every comparison is a mismatch.
#[test]
fn dumped_block_names_are_plain() {
    if !have_extract() {
        return;
    }
    let doc = read(GOLDEN);
    for entry in doc["configs"].as_array().expect("configs") {
        for target in entry["config"]["targets"].as_array().expect("targets") {
            let name = target["state"]["Name"].as_str().expect("Name");
            assert_eq!(plain_name(name), name, "{name} carries a state suffix");
        }
    }
}
